<script>document.addEventListener('DOMContentLoaded',()=>{const data=<?=json_encode(['total'=>$total,'approved'=>$approved,'considering'=>$considering,'rejected'=>$rejected],JSON_UNESCAPED_UNICODE)?>,shell=document.querySelector('.bb-shell'),title=shell?.querySelector('.bb-title');if(!shell||!title)return;title.querySelector('h1').textContent='Hasta Kayıtları';title.querySelector('p').textContent='Tüm yıllardaki hasta süreçleri ve satış sonuçları.';title.querySelector('form')?.remove();const hero=document.createElement('section');hero.className='bb-index-hero';hero.innerHTML=`<article><h2>Vox İşitme ERP</h2><p>Tüm yıllardaki hasta süreçlerini tek ekrandan takip edin.</p><div><span><b>${data.total}</b> Toplam kayıt</span><span><b>${data.approved}</b> Onaylanan</span><span><b>${data.considering}</b> Düşünecek</span><span><b>${data.rejected}</b> Reddedilen</span></div></article>`;title.after(hero);});</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const shell=document.querySelector('.bb-shell'),hero=shell?.querySelector('.bb-index-hero'),grid=shell?.querySelector('.bb-grid'),yearsCard=shell?.querySelector('.bb-card:last-child'),kpis=shell?.querySelector('.bb-kpis'),data=<?=json_encode(['total'=>$total,'approved'=>$approved,'latestTotal'=>(int)$selected['total'],'latestApproved'=>(int)$selected['approved'],'rate'=>$successRate,'latestRate'=>$yearRate,'latestYear'=>$selectedYear],JSON_UNESCAPED_UNICODE)?>;if(!shell||!hero||!grid||!yearsCard||!kpis)return;const donut=(rate,title,description,value)=>`<article class="bb-index-success"><div class="bb-index-donut" style="--rate:${rate}"><b>${rate}%</b></div><div><h3>${title}</h3><p>${description}</p><strong>${value}</strong><span>Onaylanan / toplam kayıt</span></div></article>`;grid.className='bb-index-success-grid';grid.innerHTML=donut(data.rate,'Toplam Satış Başarı Oranı','Tüm yıllarda onaylanan satışlar',`${data.approved} / ${data.total}`)+donut(data.latestRate,`${data.latestYear} Satış Başarı Oranı`,'Seçilen yılın onaylanan satışları',`${data.latestApproved} / ${data.latestTotal}`);hero.after(grid);yearsCard.classList.add('bb-index-years');yearsCard.querySelector('.bb-eyebrow').textContent='YILLARA GÖRE';yearsCard.querySelector('h2').textContent='Başarı oranı karşılaştırması';grid.after(yearsCard);kpis.classList.add('bb-index-stats');shell.append(kpis);});</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const pages={'Gelir / Gider':'income-expense','Çalışan Performansı':'employee-performance','Ürün Performansı':'product-performance','Kar Marjları':'profit-margins'};document.querySelectorAll('.bb-sidebar-menu a').forEach(link=>{const page=pages[link.textContent.trim()];if(page)link.href=<?=json_encode(url('bb/section.php?page='))?>+page;});});</script>
