<script>
if(false) document.addEventListener('DOMContentLoaded',()=>{
  const shell=document.querySelector('.bb-shell');
  if(!shell)return;
  const data=<?=json_encode(['total'=>$total,'approved'=>$approved,'considering'=>$considering,'rejected'=>$rejected,'rate'=>$successRate,'year'=>$selectedYear,'yearTotal'=>(int)$selected['total'],'yearApproved'=>(int)$selected['approved'],'yearRate'=>$yearRate,'years'=>$years],JSON_UNESCAPED_UNICODE)?>;
  const percent=(value,total)=>total?Math.round(value/total*100):0;
  const yearCards=[...data.years].reverse().map(item=>{
    const rate=percent(+item.approved,+item.total);
    return `<article class="bb-vx-year"><span>${item.year_key}</span><b>${rate}%</b><small>${item.approved} / ${item.total} onaylanan</small><i><em style="width:${rate}%"></em></i></article>`;
  }).join('');
  shell.innerHTML=`
    <section class="bb-vx-top">
      <article class="bb-vx-hero"><div><h1>Vox İşitme ERP</h1><p>Tüm yıllardaki hasta süreçlerini tek ekrandan takip edin.</p><h3>Hasta süreçleri</h3><div class="bb-vx-hero-metrics"><span><b>${data.total}</b>Toplam kayıt</span><span><b>${data.approved}</b>Onaylanan</span><span><b>${data.considering}</b>Düşünecek</span><span><b>${data.rejected}</b>Reddedilen</span></div></div></article>
      <article class="bb-vx-card bb-vx-year-card"><h2>Seçilen Yıl</h2><p>${data.year} yılı kayıt görünümü</p><strong>${data.yearTotal}</strong><span>Hasta kaydı</span><div class="bb-vx-wave"></div></article>
      <article class="bb-vx-card bb-vx-overview"><div><h2>Satış Görünümü</h2><b>%${data.yearRate}</b></div><strong>${data.yearApproved}</strong><span>Onaylanan satış</span><div class="bb-vx-split"><div><small>Düşünecek</small><b>${data.considering}</b></div><div><small>Reddedilen</small><b>${data.rejected}</b></div></div><i><em style="width:${data.yearRate}%"></em></i></article>
    </section>
    <section class="bb-vx-middle">
      <article class="bb-vx-card bb-vx-report"><div class="bb-vx-head"><div><h2>Hasta Kayıt Raporu</h2><p>Yıllık kayıt görünümü</p></div><span>•••</span></div><div class="bb-vx-report-body"><div><strong>${data.total}</strong><p>Toplam hasta kaydı</p><small>%${data.rate} başarı oranı</small></div><div class="bb-vx-bars">${[35,58,45,51,82,49,65].map((h,i)=>`<span><i style="height:${h}%"></i><small>${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'][i]}</small></span>`).join('')}</div></div><div class="bb-vx-mini"><div><span>Toplam Kayıt</span><b>${data.total}</b><i><em style="width:100%"></em></i></div><div><span>Onaylanan</span><b>${data.approved}</b><i><em style="width:${data.rate}%"></em></i></div><div><span>Düşünecek</span><b>${data.considering}</b><i><em style="width:${percent(data.considering,data.total)}%"></em></i></div></div></article>
      <article class="bb-vx-card bb-vx-tracker"><div class="bb-vx-head"><div><h2>Satış Takibi</h2><p>Tüm yıllar</p></div><span>•••</span></div><div class="bb-vx-tracker-content"><div><strong>${data.approved}</strong><p>Onaylanan satış</p><dl><dt>Toplam kayıt <b>${data.total}</b></dt><dt>Düşünecek <b>${data.considering}</b></dt><dt>Reddedilen <b>${data.rejected}</b></dt></dl></div><div class="bb-vx-gauge" style="--rate:${data.rate}"><b>%${data.rate}</b><small>Başarı oranı</small></div></div></article>
    </section>
    <section class="bb-vx-bottom">${yearCards}</section>`;
});
</script>
